const n = $input.item.json || {};
const total = n.total_net_minor;
if (!Number.isSafeInteger(total) || total < 0) throw new Error('invalid_customization_total_minor');
const bounded = (value, max, marker) => {
  if (typeof value !== 'string') throw new Error(marker);
  const clean = value.replace(/\s+/g, ' ').trim();
  if (!clean || clean.length > max) throw new Error(marker);
  return clean;
};
if (!Array.isArray(n.line_items) || n.line_items.length < 1 || n.line_items.length > 5) throw new Error('invalid_crm_line_items');
let runningLineTotal = 0;
const lineItems = n.line_items.map((item) => {
  if (!item || typeof item !== 'object' || Array.isArray(item)) throw new Error('invalid_crm_line_item');
  const quantity = item.quantity;
  const unit = item.unit_net_minor;
  const line = item.line_total_net_minor;
  if (![quantity, unit, line].every(Number.isSafeInteger) || quantity < 1 || unit < 0 || line < 0 || (unit > 0 && quantity > Math.floor(Number.MAX_SAFE_INTEGER / unit)) || unit * quantity !== line) throw new Error('invalid_crm_line_item_minor_units');
  if (runningLineTotal > Number.MAX_SAFE_INTEGER - line) throw new Error('crm_line_items_total_overflow');
  runningLineTotal += line;
  return {
    service_code: (() => {
      const code = bounded(item.service_code, 64, 'invalid_crm_service_code');
      if (!/^[a-z0-9][a-z0-9_-]{0,63}$/.test(code)) throw new Error('invalid_crm_service_code');
      return code;
    })(),
    quantity,
    unit_net_minor: unit,
    line_total_net_minor: line,
  };
});
if (runningLineTotal !== total) throw new Error('crm_line_items_total_mismatch');
const contactEmail = bounded(n.customer_email, 254, 'invalid_crm_email');
if (!/^[^\s@]+@example\.test$/i.test(contactEmail)) throw new Error('crm_fixture_email_must_use_example_test');
const currency = bounded(n.currency, 8, 'invalid_crm_currency');
if (!/^[A-Z]{3}$/.test(currency)) throw new Error('invalid_crm_currency');
return { json: {
  external_action_performed: false,
  payload_only: true,
  crm_handoff_payload: {
    offer_number: bounded(n.offer_number, 80, 'invalid_crm_offer_number'),
    company: bounded(n.company, 200, 'invalid_crm_company'),
    contact_name: bounded(n.client_name, 160, 'invalid_crm_client_name'),
    contact_email: contactEmail,
    currency,
    total_net_minor: total,
    line_items: lineItems,
  },
} };
